    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val handle: Long) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_octapass_mobile_fn_free_desktopservice(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_octapass_mobile_fn_clone_desktopservice(handle, status)
        }
    }

    
    /**
     * The socket it listens on.
     */override fun `endpoint`(): kotlin.String {
            return FfiConverterString.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_octapass_mobile_fn_method_desktopservice_endpoint(
        it,
        _status)
}
    }
    )
    }
    

    
    /**
     * Stops listening and removes the socket. Requests being answered finish.
     */override fun `stop`()
        = 
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_octapass_mobile_fn_method_desktopservice_stop(
        it,
        _status)
}
    }
    
    

    

    


    
    
    /**
     * @suppress
     */
    companion object
    
}


/**
 * @suppress
 */
public object FfiConverterTypeDesktopService: FfiConverter<DesktopService, Long> {
    override fun lower(value: DesktopService): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): DesktopService {
        return DesktopService(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): DesktopService {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: DesktopService) = 8UL

    override fun write(value: DesktopService, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


