public object FfiConverterTypeNativePlatform: FfiConverter<NativePlatform, Long> {
    internal val handleMap = UniffiHandleMap<NativePlatform>()

    override fun lower(value: NativePlatform): Long {
        if (value is NativePlatformImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): NativePlatform {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return NativePlatformImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): NativePlatform {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: NativePlatform) = 8UL

    override fun write(value: NativePlatform, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


// This template implements a class for working with a Rust struct via a handle
// to the live Rust struct on the other side of the FFI.
//
// There's some subtlety here, because we have to be careful not to operate on a Rust
// struct after it has been dropped, and because we must expose a public API for freeing
// theq Kotlin wrapper object in lieu of reliable finalizers. The core requirements are:
//
//   * Each instance holds an opaque handle to the underlying Rust struct.
//     Method calls need to read this handle from the object's state and pass it in to
//     the Rust FFI.
//
//   * When an instance is no longer needed, its handle should be passed to a
//     special destructor function provided by the Rust FFI, which will drop the
//     underlying Rust struct.
//
//   * Given an instance, calling code is expected to call the special
//     `destroy` method in order to free it after use, either by calling it explicitly
//     or by using a higher-level helper like the `use` method. Failing to do so risks
//     leaking the underlying Rust struct.
//
//   * We can't assume that calling code will do the right thing, and must be prepared
//     to handle Kotlin method calls executing concurrently with or even after a call to
//     `destroy`, and to handle multiple (possibly concurrent!) calls to `destroy`.
//
//   * We must never allow Rust code to operate on the underlying Rust struct after
//     the destructor has been called, and must never call the destructor more than once.
//     Doing so may trigger memory unsafety.
//
//   * To mitigate many of the risks of leaking memory and use-after-free unsafety, a `Cleaner`
//     is implemented to call the destructor when the Kotlin object becomes unreachable.
//     This is done in a background thread. This is not a panacea, and client code should be aware that
//      1. the thread may starve if some there are objects that have poorly performing
//     `drop` methods or do significant work in their `drop` methods.
//      2. the thread is shared across the whole library. This can be tuned by using `android_cleaner = true`,
//         or `android = true` in the [`kotlin` section of the `uniffi.toml` file](https://mozilla.github.io/uniffi-rs/kotlin/configuration.html).
//
// If we try to implement this with mutual exclusion on access to the handle, there is the
// possibility of a race between a method call and a concurrent call to `destroy`:
//
//    * Thread A starts a method call, reads the value of the handle, but is interrupted
//      before it can pass the handle over the FFI to Rust.
//    * Thread B calls `destroy` and frees the underlying Rust struct.
//    * Thread A resumes, passing the already-read handle value to Rust and triggering
//      a use-after-free.
//
// One possible solution would be to use a `ReadWriteLock`, with each method call taking
// a read lock (and thus allowed to run concurrently) and the special `destroy` method
// taking a write lock (and thus blocking on live method calls). However, we aim not to
// generate methods with any hidden blocking semantics, and a `destroy` method that might
// block if called incorrectly seems to meet that bar.
//
// So, we achieve our goals by giving each instance an associated `AtomicLong` counter to track
// the number of in-flight method calls, and an `AtomicBoolean` flag to indicate whether `destroy`
// has been called. These are updated according to the following rules:
//
//    * The initial value of the counter is 1, indicating a live object with no in-flight calls.
//      The initial value for the flag is false.
//
//    * At the start of each method call, we atomically check the counter.
//      If it is 0 then the underlying Rust struct has already been destroyed and the call is aborted.
//      If it is nonzero them we atomically increment it by 1 and proceed with the method call.
//
//    * At the end of each method call, we atomically decrement and check the counter.
//      If it has reached zero then we destroy the underlying Rust struct.
//
//    * When `destroy` is called, we atomically flip the flag from false to true.
//      If the flag was already true we silently fail.
//      Otherwise we atomically decrement and check the counter.
//      If it has reached zero then we destroy the underlying Rust struct.
//
// Astute readers may observe that this all sounds very similar to the way that Rust's `Arc<T>` works,
// and indeed it is, with the addition of a flag to guard against multiple calls to `destroy`.
//
// The overall effect is that the underlying Rust struct is destroyed only when `destroy` has been
// called *and* all in-flight method calls have completed, avoiding violating any of the expectations
// of the underlying Rust code.
//
// This makes a cleaner a better alternative to _not_ calling `destroy()` as
// and when the object is finished with, but the abstraction is not perfect: if the Rust object's `drop`
// method is slow, and/or there are many objects to cleanup, and it's on a low end Android device, then the cleaner
// thread may be starved, and the app will leak memory.
//
// In this case, `destroy`ing manually may be a better solution.
//
// The cleaner can live side by side with the manual calling of `destroy`. In the order of responsiveness, uniffi objects
// with Rust peers are reclaimed:
//
// 1. By calling the `destroy` method of the object, which calls `rustObject.free()`. If that doesn't happen:
// 2. When the object becomes unreachable, AND the Cleaner thread gets to call `rustObject.free()`. If the thread is starved then:
// 3. The memory is reclaimed when the process terminates.
//
// [1] https://stackoverflow.com/questions/24376768/can-java-finalize-an-object-when-it-is-still-in-scope/24380219
//


public interface OctaPassVaultInterface {
    
    /**
     * The keys the SSH agent offers, by title. Fails with `locked` while locked.
     */
    suspend fun `sshAgentKeys`(): List<SshAgentKey>
    
    /**
     * Serves the browser extension (plan 13) on `native-host.sock` in `data_dir` (the App Group
     * container), answering only `host_path`, the `octapass-native-host` in the app's bundle,
     * started by a known browser; in a release build only when it's signed by the app's own
     * team. `development` also answers the development extension: true in the app's debug
     * builds only. Works while locked: the extension can ask to unlock with Touch ID.
     */
    fun `startBrowserBridge`(`dataDir`: kotlin.String, `hostPath`: kotlin.String, `development`: kotlin.Boolean): DesktopService
    
    /**
     * Serves the `octapass` CLI (plan 05) on `cli.sock` in `data_dir`: the first request from a
     * terminal asks for Touch ID or the Mac's password, naming the program, and the approval lasts
     * for that program in that terminal until it's idle for 30 minutes or the vault locks.
     */
    fun `startCliSession`(`dataDir`: kotlin.String): DesktopService
    
    /**
     * Starts the SSH agent (plans 05 and 16) on `endpoint`: the vault's SSH keys while unlocked,
     * each signature asking Touch ID or the Mac's password (or `prompts.approve` on a Mac with
     * neither). A request while locked asks to unlock. `None` is `~/.octapass/agent.sock`, which
     * the sandboxed app can't make: the Mac app passes `agent.sock` in its App Group container.
     */
    fun `startSshAgent`(`prompts`: SshPromptsCallback, `endpoint`: kotlin.String?): SshAgentHandle
    
    /**
     * Whether the AutoFill extension or the Autofill services can fill without a prompt right
     * now because of the autofill gate (not stay unlocked): the fill key is on this phone.
     */
    fun `fillsWithoutPrompt`(): kotlin.Boolean
    
    /**
     * "Use on this device only": a new vault with no account, unlocked and current. Runs
     * Argon2id twice. Returns the backup recovery code, for the local Recovery Kit.
     */
    suspend fun `createLocalVault`(`name`: kotlin.String, `password`: kotlin.String): kotlin.String
    
    /**
     * Deletes the open vault from this phone for good, after the master password. Backups
     * stay where they are. Another local vault becomes current, if there is one.
     */
    suspend fun `deleteLocalVault`(`password`: kotlin.String)
    
    /**
     * A backup of the open vault in the app's private storage, for the share sheet or the
     * save dialog. `closeAttachment(path)` deletes it afterwards. Call `localBackupSaved` when
     * the user really saved it: cancelling doesn't count.
     */
    suspend fun `exportLocalBackup`(): kotlin.String
    
    /**
     * **Turn on sync**, second half: the items move into the new account as they are and the
     * local vault is removed. Show the Recovery Kit next. A wrong code can be tried again.
     */
    suspend fun `finishTurnOnSync`(`signupId`: kotlin.String, `verificationCode`: kotlin.String): RecoveryKit
    
    /**
     * Back to the first screen, to add a vault or sign in. Nothing is deleted, and the vault
     * stays in `localVaults`.
     */
    suspend fun `leaveLocalVault`()
    
    /**
     * The file from `exportLocalBackup` reached where the user chose.
     */
    suspend fun `localBackupSaved`()
    
    /**
     * Fast: call it anywhere.
     */
    fun `localCapabilities`(): LocalCapabilities
    
    /**
     * The open vault's backup recovery code. Ask for the device lock or the master password
     * first (`confirmUser`).
     */
    suspend fun `localRecoveryCode`(): kotlin.String
    
    /**
     * Every vault on this phone only. Fast: call it anywhere, signed out too.
     */
    fun `localVaults`(): List<LocalVaultInfo>
    
    suspend fun `renameLocalVault`(`name`: kotlin.String)
    
    /**
     * Restores a `.octapass-backup` file as a new vault here, unlocked and current. Fails with
     * `invalidBackup` when the file is damaged or the password or code doesn't open it.
     */
    suspend fun `restoreLocalVault`(`path`: kotlin.String, `key`: BackupKey)
    
    /**
     * Turns automatic backups on for the open vault, into `folder` (the platform's reference)
     * that the user calls `name`, and writes the first one now; both `None` turns them off. A
     * folder that can't take that backup isn't kept: the error says so and the old one stays.
     */
    suspend fun `setBackupFolder`(`folder`: kotlin.String?, `name`: kotlin.String?)
    
    /**
     * **Turn on sync**, first half: makes an account that keeps this vault's keys and items,
     * and asks the server for an email code.
     */
    suspend fun `startTurnOnSync`(`serverUrl`: kotlin.String, `email`: kotlin.String, `password`: kotlin.String): SignupStarted
    
    /**
     * Makes another local vault current. It opens locked.
     */
    suspend fun `switchLocalVault`(`tag`: kotlin.String)
    
    /**
     * The app can't be reached any more (notifications turned off, the token revoked): tells
     * the server to stop sending.
     */
    suspend fun `clearPushToken`()
    
    /**
     * Call at every launch with the token the system gave the app, and again when it changes.
     * It's sent to the signed-in account's server when that server has a push relay, now or
     * after the next sync (sign-in and unlock included). Returns whether the server has it.
     * `sandbox` is for development iPhone builds (Apple's sandbox); always false on Android.
     */
    suspend fun `setPushToken`(`platform`: PushPlatform, `token`: kotlin.String, `sandbox`: kotlin.Boolean): kotlin.Boolean
    
    /**
     * A push arrived (or a background refresh ran). Unlocked, a full sync as `sync` does.
     * Locked, the changes come down as ciphertext into the store, so AutoFill and the next unlock
     * have them; nothing is decrypted. Signed out or a local vault: nothing happens.
     */
    suspend fun `syncOnPush`()
    
    suspend fun `createSafe`(`name`: kotlin.String, `sync`: kotlin.Boolean): SafeItem
    
    /**
     * Deletes a Safe: its item (and key) goes to the trash, and its folder under `folder` goes now.
     * Lock its drive first.
     */
    suspend fun `deleteSafe`(`itemId`: kotlin.String, `folder`: kotlin.String)
    
    /**
     * The Safes on this device: every synced one, and those kept here. A Safe kept on another
     * device isn't listed, though its item syncs with the vault. `folder` is where the app keeps
     * Safes (as for `open_safe`): one made before Safes named their device lists only where its
     * folder is, or everywhere without it.
     */
    suspend fun `listSafes`(`folder`: kotlin.String? = null): List<SafeItem>
    
    /**
     * Opens a Safe kept under `folder`, which the app picks (its own private storage), making it
     * on first use.
     */
    suspend fun `openSafe`(`itemId`: kotlin.String, `folder`: kotlin.String): SafeDrive
    
    /**
     * A Safe's key, for the iPhone's Files extension: the app keeps it in the shared Keychain only
     * while the vault is unlocked (plan 03 History, 2026-11-04). Never shown, never synced.
     */
    suspend fun `safeKey`(`itemId`: kotlin.String): kotlin.ByteArray
    
    /**
     * Sends and fetches a synced Safe's changes through the server.
     */
    suspend fun `syncSafe`(`itemId`: kotlin.String, `drive`: SafeDrive): SafeSyncSummary
    
    fun `stayUnlockedStatus`(): StayUnlockedStatus
    
    /**
     * Opens the vault without a prompt when stay unlocked is on, the phone has a passcode, the
     * user didn't lock it with "Lock now", and the 14-day check isn't due. True when the vault
     * is unlocked afterwards; false means show the unlock screen as before (`passwordRequired`
     * is in `stayUnlockedStatus`). Call it when the app starts or comes back while locked.
     */
    suspend fun `unlockStayUnlocked`(): kotlin.Boolean
    
    suspend fun `acceptFamilyInvite`(`familyId`: kotlin.String)
    
    suspend fun `accountSummary`(): AccountSummary
    
    /**
     * Encrypts the file the app's picker copied to `path` into the account's outbox and lists
     * it on the item at once; it uploads when it can, offline too. The app deletes its copy.
     * Fails with `fileTooLarge` or `quotaExceeded` when the server's limits say so.
     */
    suspend fun `addAttachment`(`itemId`: kotlin.String, `path`: kotlin.String, `name`: kotlin.String, `mediaType`: kotlin.String): Item
    
    suspend fun `addEmergencyContact`(`account`: AccountLookup, `waitDays`: kotlin.UInt, `accessLevel`: EmergencyAccessLevel, `scope`: EmergencyScope): EmergencyContact
    
    /**
     * Invites `account` (from `lookupAccount`, after the user compared its fingerprint).
     */
    suspend fun `addMember`(`vaultId`: kotlin.String, `account`: AccountLookup, `role`: VaultRole)
    
    /**
     * The app went to the background: locks at once when the settings say so.
     */
    fun `appDidEnterBackground`()
    
    /**
     * The app is back: locks if it was away longer than the auto-lock time, else syncs (to
     * upload what an autofill extension saved meanwhile).
     */
    fun `appWillEnterForeground`()
    
    suspend fun `approveEmergencyAccess`(`id`: kotlin.String)
    
    /**
     * The list the item screen shows: filtered, sorted and in sections, as the web vault does.
     * With `combine_sites`, each section's `entries` show two or more logins for the same
