     */
    suspend fun `arrangeItems`(`filter`: ItemFilter, `sort`: ListSort, `grouping`: ListGrouping, `combineSites`: kotlin.Boolean = false): List<ListSection>
    
    /**
     * Organiser: cancels a pending invite.
     */
    suspend fun `cancelFamilyInvite`(`accountId`: kotlin.String)
    
    /**
     * Drops a review without saving anything.
     */
    fun `cancelImport`(`reviewId`: kotlin.String)
    
    /**
     * Drops a reset in progress: "Start over".
     */
    fun `cancelPasswordReset`(`resetId`: kotlin.String)
    
    /**
     * "Start over".
     */
    fun `cancelTwoStep`()
    
    /**
     * A new master password, after checking the current one (`invalidCredentials` when it's
     * wrong). The Secret Key and recovery code stay; every other device is signed out, and
