     */
    suspend fun `changeMasterPassword`(`currentPassword`: kotlin.String, `newPassword`: kotlin.String)
    
    suspend fun `changeRole`(`vaultId`: kotlin.String, `accountId`: kotlin.String, `role`: VaultRole)
    
    /**
     * How often the password appears in Pwned Passwords; 0 is none. Only the first five hex
