open class OctaPassVault: Disposable, AutoCloseable, OctaPassVaultInterface
{

    @Suppress("UNUSED_PARAMETER")
    /**
     * @suppress
     */
    constructor(withHandle: UniffiWithHandle, handle: Long) {
        this.handle = handle
        this.cleanable = UniffiLib.CLEANER.register(this, UniffiCleanAction(handle))
    }

    /**
     * @suppress
     *
     * This constructor can be used to instantiate a fake object. Only used for tests. Any
     * attempt to actually use an object constructed this way will fail as there is no
     * connected Rust object.
     */
    @Suppress("UNUSED_PARAMETER")
    constructor(noHandle: NoHandle) {
        this.handle = 0
        this.cleanable = null
    }
    /**
     * Opens the vault for the accounts this phone remembers. Starts locked (or signed out).
     */
    constructor(`config`: VaultConfig, `platform`: NativePlatform, `observer`: VaultObserver) :
        this(UniffiWithHandle, 
    uniffiRustCallWithError(VaultException) { _status ->
    UniffiLib.uniffi_octapass_mobile_fn_constructor_octapassvault_new(
    
        
        FfiConverterTypeVaultConfig.lower(`config`),
        FfiConverterTypeNativePlatform.lower(`platform`),
        FfiConverterTypeVaultObserver.lower(`observer`),_status)
}
    )

    protected val handle: Long
    protected val cleanable: UniffiCleaner.Cleanable?

    private val wasDestroyed = AtomicBoolean(false)
    private val callCounter = AtomicLong(1)

    /**
     * Whether the current object has been destroyed and its reference is gone in the Rust side.
     */
    val uniffiIsDestroyed: Boolean get() = wasDestroyed.get()

    override fun destroy() {
        // Only allow a single call to this method.
        // TODO: maybe we should log a warning if called more than once?
        if (this.wasDestroyed.compareAndSet(false, true)) {
            // This decrement always matches the initial count of 1 given at creation time.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    @Synchronized
    override fun close() {
        this.destroy()
    }

    internal inline fun <R> callWithHandle(block: (handle: Long) -> R): R {
        // Check and increment the call counter, to keep the object alive.
        // This needs a compare-and-set retry loop in case of concurrent updates.
        do {
            val c = this.callCounter.get()
            if (c == 0L) {
                throw IllegalStateException("${this.javaClass.simpleName} object has already been destroyed")
            }
            if (c == Long.MAX_VALUE) {
                throw IllegalStateException("${this.javaClass.simpleName} call counter would overflow")
            }
        } while (! this.callCounter.compareAndSet(c, c + 1L))
        // Now we can safely do the method call without the handle being freed concurrently.
        try {
            return block(this.uniffiCloneHandle())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val handle: Long) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_octapass_mobile_fn_free_octapassvault(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_octapass_mobile_fn_clone_octapassvault(handle, status)
        }
    }

    
    /**
     * The keys the SSH agent offers, by title. Fails with `locked` while locked.
     */
    @Throws(VaultException::class)
    @Suppress("ASSIGNED_BUT_NEVER_ACCESSED_VARIABLE")
    override suspend fun `sshAgentKeys`() : List<SshAgentKey> {
        return uniffiRustCallAsync(
        callWithHandle { uniffiHandle ->
            UniffiLib.uniffi_octapass_mobile_fn_method_octapassvault_ssh_agent_keys(
                uniffiHandle,
                
            )
        },
        { future, callback, continuation -> UniffiLib.ffi_octapass_mobile_rust_future_poll_rust_buffer(future, callback, continuation) },
        { future, continuation -> UniffiLib.ffi_octapass_mobile_rust_future_complete_rust_buffer(future, continuation) },
        { future -> UniffiLib.ffi_octapass_mobile_rust_future_free_rust_buffer(future) },
        // lift function
        { FfiConverterSequenceTypeSshAgentKey.lift(it) },
        // Error FFI converter
        VaultException.ErrorHandler,
    )
    }

    
    /**
     * Serves the browser extension (plan 13) on `native-host.sock` in `data_dir` (the App Group
     * container), answering only `host_path`, the `octapass-native-host` in the app's bundle,
     * started by a known browser; in a release build only when it's signed by the app's own
     * team. `development` also answers the development extension: true in the app's debug
     * builds only. Works while locked: the extension can ask to unlock with Touch ID.
     */
    @Throws(VaultException::class)override fun `startBrowserBridge`(`dataDir`: kotlin.String, `hostPath`: kotlin.String, `development`: kotlin.Boolean): DesktopService {
            return FfiConverterTypeDesktopService.lift(
    callWithHandle {
    uniffiRustCallWithError(VaultException) { _status ->
    UniffiLib.uniffi_octapass_mobile_fn_method_octapassvault_start_browser_bridge(
        it,
        
        FfiConverterString.lower(`dataDir`),
        FfiConverterString.lower(`hostPath`),
        FfiConverterBoolean.lower(`development`),_status)
}
    }
    )
    }
    

    
    /**
     * Serves the `octapass` CLI (plan 05) on `cli.sock` in `data_dir`: the first request from a
     * terminal asks for Touch ID or the Mac's password, naming the program, and the approval lasts
     * for that program in that terminal until it's idle for 30 minutes or the vault locks.
     */
    @Throws(VaultException::class)override fun `startCliSession`(`dataDir`: kotlin.String): DesktopService {
            return FfiConverterTypeDesktopService.lift(
    callWithHandle {
    uniffiRustCallWithError(VaultException) { _status ->
    UniffiLib.uniffi_octapass_mobile_fn_method_octapassvault_start_cli_session(
        it,
        
        FfiConverterString.lower(`dataDir`),_status)
}
    }
    )
    }
    

    
    /**
     * Starts the SSH agent (plans 05 and 16) on `endpoint`: the vault's SSH keys while unlocked,
