        { future, continuation -> UniffiLib.ffi_octapass_mobile_rust_future_complete_void(future, continuation) },
        { future -> UniffiLib.ffi_octapass_mobile_rust_future_free_void(future) },
        // lift function
        { },
        
        // Error FFI converter
