            return FfiConverterTypeSafeEntry.lift(
    callWithHandle {
    uniffiRustCallWithError(VaultException) { _status ->
    UniffiLib.uniffi_octapass_mobile_fn_method_safedrive_create_file(
        it,
        
        FfiConverterString.lower(`folder`),
        FfiConverterString.lower(`name`),_status)
}
    }
    )
    }
    

    
    @Throws(VaultException::class)override fun `createFolder`(`folder`: kotlin.String, `name`: kotlin.String): SafeEntry {
