 * Enterprise kinds, and a save drops the ones the security type doesn't use, as the web vault's
 * editor does.
 */
data class WifiDetails (
    /**
     * The network name, exactly as broadcast: spaces at either end are kept.
     */
    var `ssid`: kotlin.String
    , 
    /**
     * `wpa2`, `wpa2Wpa3`, `wpa3`, `wpaWpa2`, `wpa`, `wep`, `open`, `wpa2Enterprise` or
     * `wpa3Enterprise` (`WIFI_SECURITIES`), or a newer one.
     */
    var `security`: kotlin.String
    , 
    /**
     * The shared password (Personal, WEP), or the user's own on an Enterprise network.
     */
    var `password`: kotlin.String?
    , 
    /**
     * The network doesn't broadcast its name.
     */
    var `hidden`: kotlin.Boolean
    , 
    /**
     * Enterprise: `peap`, `ttls`, `tls`, `pwd`, `leap` or `fast`.
     */
    var `eapMethod`: kotlin.String?
    , 
    /**
     * Enterprise, PEAP and TTLS: `mschapv2`, `gtc`, `pap`, `chap` or `mschap`.
     */
    var `phase2`: kotlin.String?
    , 
    var `username`: kotlin.String?
    , 
    /**
     * Enterprise: the outer (anonymous) identity, when it differs from the username.
     */
    var `identity`: kotlin.String?
    , 
    /**
     * Enterprise: the domain the server's certificate must match.
     */
    var `serverDomain`: kotlin.String?
    , 
    /**
     * Enterprise: the CA certificate (PEM) that signed the server's certificate.
     */
    var `caCertificate`: kotlin.String?
    , 
    /**
     * Shows a sign-in page after joining, as in hotels and airports.
     */
    var `captivePortal`: kotlin.Boolean
    , 
    /**
     * Set up by an organisation: the user's own note, not the system's state.
     */
    var `managed`: kotlin.Boolean
    , 
    /**
     * A phone's or tablet's Personal Hotspot.
     */
    var `hotspot`: kotlin.Boolean
    , 
    var `notes`: kotlin.String?
    , 
    var `customFields`: List<CustomField>
    , 
    /**
     * Newest first. Read-only.
     */
    var `passwordHistory`: List<PasswordHistoryEntry>
    
){
    

    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeWifiDetails: FfiConverterRustBuffer<WifiDetails> {
    override fun read(buf: ByteBuffer): WifiDetails {
        return WifiDetails(
            FfiConverterString.read(buf),
            FfiConverterString.read(buf),
            FfiConverterOptionalString.read(buf),
            FfiConverterBoolean.read(buf),
            FfiConverterOptionalString.read(buf),
            FfiConverterOptionalString.read(buf),
            FfiConverterOptionalString.read(buf),
            FfiConverterOptionalString.read(buf),
            FfiConverterOptionalString.read(buf),
            FfiConverterOptionalString.read(buf),
            FfiConverterBoolean.read(buf),
            FfiConverterBoolean.read(buf),
            FfiConverterBoolean.read(buf),
            FfiConverterOptionalString.read(buf),
            FfiConverterSequenceTypeCustomField.read(buf),
            FfiConverterSequenceTypePasswordHistoryEntry.read(buf),
        )
    }

    override fun allocationSize(value: WifiDetails) = (
            FfiConverterString.allocationSize(value.`ssid`) +
            FfiConverterString.allocationSize(value.`security`) +
            FfiConverterOptionalString.allocationSize(value.`password`) +
            FfiConverterBoolean.allocationSize(value.`hidden`) +
            FfiConverterOptionalString.allocationSize(value.`eapMethod`) +
            FfiConverterOptionalString.allocationSize(value.`phase2`) +
            FfiConverterOptionalString.allocationSize(value.`username`) +
            FfiConverterOptionalString.allocationSize(value.`identity`) +
            FfiConverterOptionalString.allocationSize(value.`serverDomain`) +
            FfiConverterOptionalString.allocationSize(value.`caCertificate`) +
            FfiConverterBoolean.allocationSize(value.`captivePortal`) +
            FfiConverterBoolean.allocationSize(value.`managed`) +
            FfiConverterBoolean.allocationSize(value.`hotspot`) +
            FfiConverterOptionalString.allocationSize(value.`notes`) +
            FfiConverterSequenceTypeCustomField.allocationSize(value.`customFields`) +
            FfiConverterSequenceTypePasswordHistoryEntry.allocationSize(value.`passwordHistory`)
    )

    override fun write(value: WifiDetails, buf: ByteBuffer) {
            FfiConverterString.write(value.`ssid`, buf)
            FfiConverterString.write(value.`security`, buf)
            FfiConverterOptionalString.write(value.`password`, buf)
            FfiConverterBoolean.write(value.`hidden`, buf)
            FfiConverterOptionalString.write(value.`eapMethod`, buf)
            FfiConverterOptionalString.write(value.`phase2`, buf)
            FfiConverterOptionalString.write(value.`username`, buf)
            FfiConverterOptionalString.write(value.`identity`, buf)
            FfiConverterOptionalString.write(value.`serverDomain`, buf)
            FfiConverterOptionalString.write(value.`caCertificate`, buf)
            FfiConverterBoolean.write(value.`captivePortal`, buf)
            FfiConverterBoolean.write(value.`managed`, buf)
            FfiConverterBoolean.write(value.`hotspot`, buf)
            FfiConverterOptionalString.write(value.`notes`, buf)
            FfiConverterSequenceTypeCustomField.write(value.`customFields`, buf)
            FfiConverterSequenceTypePasswordHistoryEntry.write(value.`passwordHistory`, buf)
    }
}



