/**
 * What opens a backup file.
 */
sealed class BackupKey {
    
    /**
     * The master password it was made with, which stays the vault's.
     */
    data class Password(
        val `password`: kotlin.String) : BackupKey()
        
    {
        

        companion object
    }
    
    /**
     * The backup recovery code, and the master password to set instead.
     */
    data class RecoveryCode(
        val `code`: kotlin.String, 
        val `newPassword`: kotlin.String) : BackupKey()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeBackupKey : FfiConverterRustBuffer<BackupKey>{
    override fun read(buf: ByteBuffer): BackupKey {
        return when(buf.getInt()) {
            1 -> BackupKey.Password(
                FfiConverterString.read(buf),
                )
            2 -> BackupKey.RecoveryCode(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: BackupKey): ULong = when(value) {
        is BackupKey.Password -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`password`)
            )
        }
        is BackupKey.RecoveryCode -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`newPassword`)
            )
        }
    }

    override fun write(value: BackupKey, buf: ByteBuffer) {
        when(value) {
            is BackupKey.Password -> {
                buf.putInt(1)
                FfiConverterString.write(value.`password`, buf)
                Unit
            }
            is BackupKey.RecoveryCode -> {
                buf.putInt(2)
                FfiConverterString.write(value.`code`, buf)
                FfiConverterString.write(value.`newPassword`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





/**
 * What the system's credential lists need (`ASCredentialIdentityStore` on iOS, the Credential
 * Manager entries on Android), so suggestions show before the vault is unlocked. No secrets.
 */
sealed class CredentialIdentity {
    
    /**
     * One per saved URL of a login with a password.
     */
    data class Password(
        val `itemId`: kotlin.String, 
        val `url`: kotlin.String, 
        val `user`: kotlin.String) : CredentialIdentity()
        
    {
        

        companion object
    }
    
    data class Passkey(
        val `itemId`: kotlin.String, 
        val `rpId`: kotlin.String, 
        val `userName`: kotlin.String, 
        val `credentialId`: kotlin.ByteArray, 
        val `userHandle`: kotlin.ByteArray) : CredentialIdentity()
        
    {
        

        companion object
    }
    
    /**
     * One per saved URL of a login with a one-time code secret.
     */
    data class OneTimeCode(
        val `itemId`: kotlin.String, 
        val `url`: kotlin.String, 
        val `label`: kotlin.String) : CredentialIdentity()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeCredentialIdentity : FfiConverterRustBuffer<CredentialIdentity>{
    override fun read(buf: ByteBuffer): CredentialIdentity {
        return when(buf.getInt()) {
            1 -> CredentialIdentity.Password(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            2 -> CredentialIdentity.Passkey(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterByteArray.read(buf),
                FfiConverterByteArray.read(buf),
                )
            3 -> CredentialIdentity.OneTimeCode(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CredentialIdentity): ULong = when(value) {
        is CredentialIdentity.Password -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`itemId`)
                + FfiConverterString.allocationSize(value.`url`)
                + FfiConverterString.allocationSize(value.`user`)
            )
        }
        is CredentialIdentity.Passkey -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`itemId`)
                + FfiConverterString.allocationSize(value.`rpId`)
                + FfiConverterString.allocationSize(value.`userName`)
                + FfiConverterByteArray.allocationSize(value.`credentialId`)
                + FfiConverterByteArray.allocationSize(value.`userHandle`)
            )
        }
        is CredentialIdentity.OneTimeCode -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`itemId`)
                + FfiConverterString.allocationSize(value.`url`)
                + FfiConverterString.allocationSize(value.`label`)
            )
        }
    }

    override fun write(value: CredentialIdentity, buf: ByteBuffer) {
        when(value) {
            is CredentialIdentity.Password -> {
                buf.putInt(1)
                FfiConverterString.write(value.`itemId`, buf)
                FfiConverterString.write(value.`url`, buf)
                FfiConverterString.write(value.`user`, buf)
                Unit
            }
            is CredentialIdentity.Passkey -> {
                buf.putInt(2)
                FfiConverterString.write(value.`itemId`, buf)
                FfiConverterString.write(value.`rpId`, buf)
                FfiConverterString.write(value.`userName`, buf)
                FfiConverterByteArray.write(value.`credentialId`, buf)
                FfiConverterByteArray.write(value.`userHandle`, buf)
                Unit
            }
            is CredentialIdentity.OneTimeCode -> {
                buf.putInt(3)
                FfiConverterString.write(value.`itemId`, buf)
                FfiConverterString.write(value.`url`, buf)
                FfiConverterString.write(value.`label`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






