    WRONG_IMPORT_PASSWORD,
    EMAIL_MISMATCH,
    DEVICE_UNLOCK_UNSUPPORTED,
    DEVICE_UNLOCK_CANCELLED,
    DEVICE_UNLOCK_FAILED,
    PASSWORD_REQUIRED,
    ACCOUNT_NOT_FOUND,
    NOT_ALLOWED,
    ALREADY_EXISTS,
    FAMILY_FULL,
    QUOTA_EXCEEDED,
    UNTRUSTED_VAULT,
    WRONG_PASSPHRASE,
