/**
 * The web vault's generator settings.
 */
sealed class GeneratorOptions {
    
    /**
     * 4–128 characters from the chosen sets, at least one of each.
     */
    data class Password(
        val `length`: kotlin.UInt, 
        val `uppercase`: kotlin.Boolean, 
        val `lowercase`: kotlin.Boolean, 
        val `digits`: kotlin.Boolean, 
        val `symbols`: kotlin.Boolean, 
        /**
         * Leaves out look-alikes such as `0 O 1 l I`.
         */
        val `avoidAmbiguous`: kotlin.Boolean) : GeneratorOptions()
        
    {
        

        companion object
    }
    
    /**
     * 3–20 words from the EFF large wordlist.
     */
    data class Passphrase(
        val `words`: kotlin.UInt, 
        val `separator`: kotlin.String, 
        val `capitalize`: kotlin.Boolean, 
        val `includeNumber`: kotlin.Boolean) : GeneratorOptions()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeGeneratorOptions : FfiConverterRustBuffer<GeneratorOptions>{
    override fun read(buf: ByteBuffer): GeneratorOptions {
        return when(buf.getInt()) {
            1 -> GeneratorOptions.Password(
                FfiConverterUInt.read(buf),
                FfiConverterBoolean.read(buf),
                FfiConverterBoolean.read(buf),
                FfiConverterBoolean.read(buf),
                FfiConverterBoolean.read(buf),
                FfiConverterBoolean.read(buf),
                )
